273	// Adam-only on pre-amplified gradient (no psi network evaluation).
274	__global__ void neuralgrok_adam_only_kernel(
275	    float* param, float* exp_avg, float* exp_avg_sq,
276	    const float* amplified_grad,
277	    float beta1, float beta2, float lr, float wd, float eps,
278	    float bc1, float bc2, int64_t N
279	) {
280	    const int64_t stride = prim::grid_stride();
281	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
282	        // g_eff is the pre-amplified gradient; the bias-corrected Adam +
283	        // decoupled-WD math lives once in algorithms/neuralgrok.h.
284	        const float g_eff = ::grokking::sm90::sg_sanitize_grad(amplified_grad[i]);
285	        neuralgrok_adam_tail(param, exp_avg, exp_avg_sq, g_eff,
286	                             lr, beta1, beta2, eps, wd, bc1, bc2, i);
287	    }
288	}
