290	void launch_fused_neuralgrok_adam(
291	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
292	    torch::Tensor amplified_grad,
293	    float beta1, float beta2, float lr, float weight_decay, float eps,
294	    float bc1, float bc2
295	) {
296	    const int64_t N = param.numel();
297	    if (N == 0) return;
298	    auto stream = at::cuda::getCurrentCUDAStream().stream();
299	    const int block = SG_TUNED_BLOCK_SIZE;
300	    const int grid = static_cast<int>(
301	        std::min<int64_t>(65535, (N + block - 1) / block));
302	    neuralgrok_adam_only_kernel<<<grid, block, 0, stream>>>(
