304	        exp_avg_sq.data_ptr<float>(), amplified_grad.data_ptr<float>(),
305	        beta1, beta2, lr, weight_decay, eps, bc1, bc2, N);
306	    SG_LAUNCH_CHECK(stream);
307	}
