309	// Full fused step: psi amplification + Adam update in a single kernel launch.
310	void launch_fused_neuralgrok_full_step(
311	    torch::Tensor param, torch::Tensor exp_avg, torch::Tensor exp_avg_sq,
312	    torch::Tensor grad,
313	    torch::Tensor W1, torch::Tensor b1, torch::Tensor W2, torch::Tensor b2,
314	    float alpha_amp, float beta_amp, int hidden_dim,
315	    float beta1, float beta2, float lr, float weight_decay, float eps,
316	    float bc1, float bc2
317	) {
318	    float b2_val = b2.item<float>();
319	    launch_neuralgrok_step(param, exp_avg, exp_avg_sq, grad,
320	                           W1, b1, W2, b2_val,
321	                           alpha_amp, beta_amp,
322	                           lr, beta1, beta2, eps, weight_decay, bc1, bc2);
