91	// ── Boundary validation for optimizer fused-step entrypoints ─────────
92	// The Python wrappers historically owned device/dtype/shape/contiguity
93	// invariants; these binding entrypoints trusted them. A non-contiguous param
94	// view, a device/dtype mismatch between param and grad, or a shape mismatch
95	// silently corrupts the in-place fused update (the launchers index a flat
96	// pointer with the param's numel). Validate at the C++ boundary so a bad call
97	// fails loudly. `where` is the entrypoint name for the error message.
98	//
99	// We check the param against its paired grad. Optimizer-state buffers (m, v,
100	// ema, …) are allocated by the wrapper from `torch.zeros_like(param)` so they
101	// inherit the param's device/dtype/shape/contiguity; the param check is the
102	// load-bearing one. A missing/empty grad (sparse-grad fallback) is skipped —
103	// the per-op loops already filter those out before dispatch.
104	inline void check_param_grad(
105	    const torch::Tensor& p,
106	    const torch::Tensor& g,
107	    const char* where
108	) {
109	    TORCH_CHECK(p.defined(), where, ": param tensor is undefined");
110	#if defined(WITH_HIP)
111	    TORCH_CHECK(p.is_hip(), where, ": param must be on a HIP device");
112	#else
113	    TORCH_CHECK(p.is_cuda(), where, ": param must be on a CUDA device");
114	#endif
115	    // A non-contiguous param view aliases a strided storage; the fused
116	    // launchers treat data_ptr() as a dense [numel] buffer, so a strided view
117	    // would read/write the wrong elements and silently corrupt the update.
118	    TORCH_CHECK(p.is_contiguous(), where,
119	                ": param must be contiguous (got a non-contiguous view); "
120	                "call .contiguous() in the Python wrapper before the fused step");
121	    if (!g.defined() || g.numel() == 0) return;  // sparse-grad: skip (filtered)
122	    TORCH_CHECK(g.device() == p.device(), where,
123	                ": grad device (", g.device().str(),
124	                ") != param device (", p.device().str(), ")");
125	    TORCH_CHECK(g.scalar_type() == p.scalar_type(), where,
126	                ": grad dtype (", toString(g.scalar_type()),
127	                ") != param dtype (", toString(p.scalar_type()), ")");
128	    TORCH_CHECK(g.sizes() == p.sizes(), where,
129	                ": grad shape (", g.sizes(), ") != param shape (",
130	                p.sizes(), ")");
131	    TORCH_CHECK(g.is_contiguous(), where, ": grad must be contiguous");
132	}
