147	// ── Device-side gradient clipping: single CPU sync instead of N ──────
148	inline void clip_grad_norms_device_side(
149	    std::vector<torch::Tensor>& grads,
150	    size_t n_params,
151	    float grad_clip_norm
152	) {
153	    if (grad_clip_norm <= 0.0f) return;
154	
155	    // Collect the present grads once. Fused multi-tensor ops want a flat list.
156	    std::vector<torch::Tensor> present;
157	    present.reserve(n_params);
158	    for (size_t i = 0; i < n_params; i++) {
159	        if (grads[i].defined() && grads[i].numel() > 0)
160	            present.push_back(grads[i]);
161	    }
162	    if (present.empty()) return;
163	
164	    // Per-tensor L2 norms via a single fused multi-tensor reduction
165	    // (torch::_foreach_norm), replacing the per-tensor upcast + dot + add_
166	    // (≈2N kernel launches) with one foreach launch. Numerics: the L2 norm of
167	    // each tensor is accumulated into a fp32 sum-of-squares (squaring the
168	    // per-tensor norm == that tensor's sum-of-squares), matching the original
169	    // fp32 accumulation of the global sum-of-squares. To preserve the original
170	    // precision when grads are NOT already fp32, upcast those (only) to fp32
171	    // before the norm; fp32 grads skip the upcast entirely.
172	    bool all_fp32 = true;
173	    for (auto& g : present)
174	        if (g.scalar_type() != torch::kFloat32) { all_fp32 = false; break; }
175	
176	    std::vector<torch::Tensor> norm_inputs;
177	    if (all_fp32) {
178	        norm_inputs = present;
179	    } else {
180	        norm_inputs.reserve(present.size());
181	        for (auto& g : present)
182	            norm_inputs.push_back(g.scalar_type() == torch::kFloat32
183	                                      ? g
184	                                      : g.to(torch::kFloat32));
185	    }
186	
187	    auto norms = torch::_foreach_norm(norm_inputs, /*p=*/2);
188	    // norm_sq = sum_i (||g_i||_2)^2, accumulated in fp32 on-device, one sync.
189	    auto stacked = torch::stack(norms).to(torch::kFloat32);
190	    float total_norm =
191	        std::sqrt(stacked.dot(stacked).item<float>());
192	
193	    if (total_norm > grad_clip_norm) {
194	        float clip_coef = grad_clip_norm / (total_norm + 1e-6f);
195	        // Fused multi-tensor in-place scale of the present grads.
196	        torch::_foreach_mul_(present, clip_coef);
197	    }
198	}
